import ProductCard from "./ProductCard";
import { ChevronRight } from "lucide-react";
import { Link } from "react-router-dom";

export default function ProductSection({ title, subtitle, products, viewMoreLink = "/categories" }) {
  if (!products?.length) return null;

  const shouldScroll = products.length > 8;

  return (
    <section className="py-10">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-end justify-between mb-6">
          <div>
            <div className="uppercase-tracked text-xs text-[#D97706] mb-1">{subtitle}</div>
            <h2 className="font-display text-2xl md:text-3xl font-bold">{title}</h2>
          </div>
          <Link to={viewMoreLink} className="text-sm uppercase-tracked text-[#D97706] flex items-center gap-1 hover:gap-2 transition-all">
            View More <ChevronRight className="w-4 h-4" />
          </Link>
        </div>

        {shouldScroll ? (
          <div className="overflow-x-auto pb-2">
            <div className="grid grid-flow-col grid-rows-2 gap-4 md:gap-6 auto-cols-[85%] sm:auto-cols-[45%] lg:auto-cols-[22%] min-w-max">
              {products.map((p) => (
                <div key={p.id} className="min-w-[220px] sm:min-w-[240px] lg:min-w-[260px]">
                  <ProductCard product={p} />
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
            {products.slice(0, 8).map((p) => <ProductCard key={p.id} product={p} />)}
          </div>
        )}
      </div>
    </section>
  );
}
